/**
 * Typed SDK module for the StellarKit `/utils/*` endpoints.
 *
 * Covers convert, validateAccount, validateAsset, ledgerDate, decodeXdr and
 * fundTestnetAccount. `/utils/keypair` is deliberately NOT wrapped: secrets
 * must be generated locally by the caller (e.g. with `Keypair.random()`), and
 * never transmitted to or generated by a remote service.
 */

/** Typed error thrown by UtilsModule on non-2xx API responses. */
export class StellarKitError extends Error {
  /** HTTP status code returned by the API. */
  readonly status: number;
  /** Machine-readable error type from the API error envelope. */
  readonly type: string;

  constructor(message: string, status: number, type: string) {
    super(message);
    this.name = "StellarKitError";
    this.status = status;
    this.type = type;
  }
}

/** Typed error thrown when a testnet-only operation is used on mainnet. */
export class MainnetNotSupportedError extends StellarKitError {
  constructor(operation: string) {
    super(
      `${operation} is only available on testnet; the client is configured for mainnet.`,
      403,
      "MainnetNotSupported",
    );
    this.name = "MainnetNotSupportedError";
  }
}

/** Result of converting between XLM and stroops. */
export interface ConvertResult {
  /** Amount in XLM with seven decimal places. */
  xlm: string;
  /** Amount in stroops (integer). */
  stroops: number;
}

/** Result of validating a Stellar public key. */
export interface ValidateAccountResult {
  /** Original input. */
  input?: string;
  /** Whether the account id is valid. */
  isValid: boolean;
  /** Human-readable validation reason. */
  reason?: string | null;
}

/** Result of validating a Stellar asset code. */
export interface ValidateAssetResult {
  /** Original input. */
  input?: string;
  /** Whether the asset code is valid. */
  isValid: boolean;
  /** Native, credit_alphanum4 or credit_alphanum12. */
  assetType?: string | null;
  /** Human-readable validation reason. */
  reason?: string | null;
}

/** Estimated close time for a ledger sequence. */
export interface LedgerDateResult {
  /** Ledger sequence queried. */
  sequence: number;
  /** Estimated ISO-8601 close timestamp. */
  estimatedDate: string;
  /** Explanation of the approximation. */
  note: string;
}

/** Decoded transaction XDR envelope. */
export interface DecodeXdrResult {
  /** Number of operations in the transaction. */
  fee?: number | string;
  /** Source account public key. */
  sourceAccount?: string;
  /** Decoded operations. */
  operations: unknown[];
  /** Decoded memo fields. */
  memo?: Record<string, unknown>;
  [key: string]: unknown;
}

/** Result of funding an account via Friendbot. */
export interface FundTestnetAccountResult {
  /** Funded account public key. */
  accountId: string;
  /** Confirmation message. */
  message: string;
  /** Raw Friendbot transaction response. */
  transaction: unknown;
}

/** Options accepted by every UtilsModule instance. */
export interface UtilsModuleOptions {
  /** Base URL of the StellarKit API (trailing slash stripped). */
  baseUrl: string;
  /** Optional API key sent as the `X-API-Key` header. */
  apiKey?: string;
  /** Configured Stellar network; `mainnet` disables Friendbot. */
  network?: string;
}

/**
 * UtilsModule wraps the server-side utility endpoints.
 *
 * @example
 * ```ts
 * const utils = new UtilsModule({ baseUrl: "http://localhost:3000", network: "testnet" });
 * const converted = await utils.convert({ stroops: 10000000 });
 * const validation = await utils.validateAccount("GABC...");
 * ```
 */
export class UtilsModule {
  private readonly baseUrl: string;
  private readonly headers: Record<string, string>;
  private readonly network: string;

  /** @param options - {@link UtilsModuleOptions} */
  constructor({ baseUrl, apiKey, network }: UtilsModuleOptions) {
    if (!baseUrl) throw new Error("baseUrl is required");
    this.baseUrl = baseUrl.replace(/\/$/, "");
    this.headers = {
      "Content-Type": "application/json",
      Accept: "application/json",
    };
    if (apiKey) this.headers["X-API-Key"] = apiKey;
    this.network = network ?? process.env.STELLAR_NETWORK ?? "testnet";
  }

  /** @private GET helper that unwraps `data` and throws typed errors. */
  private async _get<T>(path: string): Promise<T> {
    const res = await fetch(`${this.baseUrl}${path}`, { headers: this.headers });
    const body = await res.json();
    if (!res.ok) {
      throw new StellarKitError(
        body?.error?.message ?? res.statusText,
        res.status,
        body?.error?.type ?? "ApiError",
      );
    }
    return (body as { data: T }).data;
  }

  /** @private POST helper that unwraps `data` and throws typed errors. */
  private async _post<T>(path: string, payload: unknown): Promise<T> {
    const res = await fetch(`${this.baseUrl}${path}`, {
      method: "POST",
      headers: this.headers,
      body: JSON.stringify(payload),
    });
    const body = await res.json();
    if (!res.ok) {
      throw new StellarKitError(
        body?.error?.message ?? res.statusText,
        res.status,
        body?.error?.type ?? "ApiError",
      );
    }
    return (body as { data: T }).data;
  }

  /**
   * Convert between XLM and stroops. Provide exactly one of `xlm`/`stroops`.
   *
   * @param amount - Conversion input.
   * @returns The converted amount in both units.
   * @throws {StellarKitError} On non-2xx response or invalid input.
   * @example
   * ```ts
   * const result = await utils.convert({ xlm: "1.5" });
   * console.log(result.stroops); // 15000000
   * ```
   */
  async convert(amount: { xlm: string | number } | { stroops: number }): Promise<ConvertResult> {
    const params = new URLSearchParams();
    if ("xlm" in amount) params.set("xlm", String(amount.xlm));
    if ("stroops" in amount) params.set("stroops", String(amount.stroops));
    return this._get<ConvertResult>(`/utils/convert?${params}`);
  }

  /**
   * Validate a Stellar public key without a Horizon call.
   *
   * @param accountId - The account id to validate.
   * @returns Validation result.
   * @throws {StellarKitError} On non-2xx response.
   * @example
   * ```ts
   * const { isValid } = await utils.validateAccount("GABC...");
   * ```
   */
  async validateAccount(accountId: string): Promise<ValidateAccountResult> {
    const params = new URLSearchParams({ id: accountId });
    return this._get<ValidateAccountResult>(`/utils/validate-account?${params}`);
  }

  /**
   * Validate a Stellar asset code.
   *
   * @param code - Asset code (e.g. `USDC`).
   * @returns Validation result including the detected asset type.
   * @throws {StellarKitError} On non-2xx response.
   * @example
   * ```ts
   * const result = await utils.validateAsset("USDC");
   * ```
   */
  async validateAsset(code: string): Promise<ValidateAssetResult> {
    const params = new URLSearchParams({ code });
    return this._get<ValidateAssetResult>(`/utils/validate-asset?${params}`);
  }

  /**
   * Estimate the approximate close date for a ledger sequence.
   *
   * @param sequence - Positive Stellar ledger sequence.
   * @returns Estimated close timestamp.
   * @throws {StellarKitError} On non-2xx response.
   * @example
   * ```ts
   * const { estimatedDate } = await utils.ledgerDate(1234567);
   * ```
   */
  async ledgerDate(sequence: number): Promise<LedgerDateResult> {
    const params = new URLSearchParams({ sequence: String(sequence) });
    return this._get<LedgerDateResult>(`/utils/ledger-date?${params}`);
  }

  /**
   * Decode a base64-encoded Stellar transaction XDR envelope.
   *
   * @param xdr - Base64 XDR envelope.
   * @returns Decoded transaction fields and operations.
   * @throws {StellarKitError} On non-2xx response.
   * @example
   * ```ts
   * const decoded = await utils.decodeXdr("AAAAAgAAAAD...");
   * console.log(decoded.operations);
   * ```
   */
  async decodeXdr(xdr: string): Promise<DecodeXdrResult> {
    return this._post<DecodeXdrResult>("/utils/decode-xdr", { xdr });
  }

  /**
   * Fund a testnet account via Friendbot.
   *
   * This is intentionally unavailable when the client is configured for
   * mainnet; use a real funding transaction there instead.
   *
   * @param accountId - Stellar public key to fund.
   * @returns Friendbot funding confirmation.
   * @throws {MainnetNotSupportedError} When configured for mainnet.
   * @throws {StellarKitError} On non-2xx response.
   * @example
   * ```ts
   * const funded = await utils.fundTestnetAccount("GABC...");
   * ```
   */
  async fundTestnetAccount(accountId: string): Promise<FundTestnetAccountResult> {
    if (this.network === "mainnet" || this.network === "public") {
      throw new MainnetNotSupportedError("fundTestnetAccount");
    }
    return this._get<FundTestnetAccountResult>(
      `/utils/friendbot/${encodeURIComponent(accountId)}`,
    );
  }
}

// CommonJS/UMD compatibility, matching the other SDK modules.
(UtilsModule as any).default = UtilsModule;
(UtilsModule as any).StellarKitError = StellarKitError;
(UtilsModule as any).MainnetNotSupportedError = MainnetNotSupportedError;
if (typeof module !== "undefined" && module.exports) {
  module.exports = UtilsModule;
  module.exports.StellarKitError = StellarKitError;
  module.exports.MainnetNotSupportedError = MainnetNotSupportedError;
} else if (typeof window !== "undefined") {
  (window as any).UtilsModule = UtilsModule;
}
